// ── activity_feed SSE Handler ──

async fn activity_feed_sse(
    State(state): State<Arc<AppState>>,
) -> Sse<impl futures::Stream<Item = Result<Event, Infallible>>> {
    let rx = activity::activity_feed(&state);
    sse_stream("activity-feed", rx, ontogen_core::events::no_id)
}

// ── activity_for_kind SSE Handler ──

#[derive(Deserialize)]
struct ActivityActivityForKindEventQuery {
    resume: Option<String>,
}

async fn activity_for_kind_sse(
    State(state): State<Arc<AppState>>,
    Path(kind): Path<String>,
    q: Result<axum::extract::Query<ActivityActivityForKindEventQuery>, QueryRejection>,
    headers: axum::http::HeaderMap,
) -> Result<Sse<impl futures::Stream<Item = Result<Event, Infallible>>>, ErrorObject> {
    let axum::extract::Query(q) = q.map_err(query_rejection)?;
    let resume = ontogen_core::events::last_event_id(headers.get("last-event-id").map(|v| v.as_bytes())).or(q.resume);
    let rx = activity::activity_for_kind(&state, kind, resume).await.map_err(internal_error)?;
    Ok(sse_stream("activity-for-kind", rx, ontogen_core::events::seq_id))
}

/// Generated routes. Call this from your main router.
pub fn entity_routes() -> Router<Arc<AppState>> {
    Router::new()
        .route("/api/exercises", get(exercise_list).post(exercise_create).fallback(allow([Method::GET, Method::POST])))
        .route(
            "/api/exercises/{id}",
            get(exercise_get_by_id).patch(exercise_update).delete(exercise_delete).fallback(allow([
                Method::GET,
                Method::PATCH,
                Method::DELETE,
            ])),
        )
        .route("/api/tags", get(tag_list).post(tag_create).fallback(allow([Method::GET, Method::POST])))
        .route(
            "/api/tags/{id}",
            get(tag_get_by_id).patch(tag_update).delete(tag_delete).fallback(allow([
                Method::GET,
                Method::PATCH,
                Method::DELETE,
            ])),
        )
        .route("/api/workouts", get(workout_list).post(workout_create).fallback(allow([Method::GET, Method::POST])))
        .route(
            "/api/workouts/{id}",
            get(workout_get_by_id).patch(workout_update).delete(workout_delete).fallback(allow([
                Method::GET,
                Method::PATCH,
                Method::DELETE,
            ])),
        )
        .route(
            "/api/workout-sets",
            get(workout_set_list).post(workout_set_create).fallback(allow([Method::GET, Method::POST])),
        )
        .route(
            "/api/workout-sets/{id}",
            get(workout_set_get_by_id).patch(workout_set_update).delete(workout_set_delete).fallback(allow([
                Method::GET,
                Method::PATCH,
                Method::DELETE,
            ])),
        )
        .route("/api/stats/workout", get(stat_get_workout).fallback(allow([Method::GET])))
        .route("/api/events/activity-feed", get(activity_feed_sse).fallback(allow([Method::GET])))
        .route("/api/events/activity-for-kind/{kind}", get(activity_for_kind_sse).fallback(allow([Method::GET])))
}
